/**
 * Global constants for the CLI
 */
import { join } from 'path';
import { homedir } from 'os';
// =============================================================================
// PATHS
// =============================================================================
/**
 * CLI config directory (~/.lua-cli)
 */
export const CLI_CONFIG_DIR = join(homedir(), '.lua-cli');
/**
 * Version check cache file
 */
export const VERSION_CHECK_FILE = join(CLI_CONFIG_DIR, 'version-check.json');
/**
 * Telemetry config file
 */
export const TELEMETRY_FILE = join(CLI_CONFIG_DIR, 'telemetry.json');
// =============================================================================
// API URLS
// =============================================================================
/**
 * Base URLs for the API, Auth, and Chat
 */
export const BASE_URLS = {
    API: process.env.LUA_API_URL || 'https://api.heylua.ai',
    AUTH: process.env.LUA_AUTH_URL || 'https://auth.heylua.ai',
    CHAT: process.env.LUA_API_URL || 'https://api.heylua.ai',
    WEBHOOK: 'https://webhook.heylua.ai',
    CDN: 'https://cdn.heylua.ai',
};
// =============================================================================
// AUTH CONSTANTS
// =============================================================================
/**
 * Credentials file path for storing the API key (~/.lua-cli/credentials).
 * Written by `lua auth configure`, read by getToken().
 * Owner-only permissions (0600) are applied on write.
 */
export const CREDENTIALS_FILE = join(CLI_CONFIG_DIR, 'credentials');
// =============================================================================
// INIT CONSTANTS
// =============================================================================
/**
 * Agent type names to search for (in order of preference)
 */
export const PREFERRED_AGENT_TYPES = [
    'Base Agent',
    'baseAgent',
    'base',
];
// =============================================================================
// SANDBOX STORAGE CONSTANTS
// =============================================================================
/**
 * Sandbox ID storage file path (~/.lua-cli/sandbox.json).
 * Stores transient sandbox skill/preprocessor/postprocessor IDs for local dev.
 */
export const SANDBOX_STORAGE_FILE = join(CLI_CONFIG_DIR, 'sandbox.json');
